presets.css:
/* ============================================================
   仿 QQ 风格即时对话主题（稳定版 · 顶栏/底栏/加号面板 全部正常可点）
   + 灰白描边猫耳气泡
   + 输入框右上角装饰图
   + 输入栏上方装饰图
   ============================================================ */

.chat-thread {
  /* ==================== 1. 【顶栏尺寸与排版】 ==================== */
  --qq-header-height: 88px;
  --qq-header-safe-bottom: 12px;

  --qq-top-btn-size: 42px;
  --qq-back-offset-x: 0px;
  --qq-back-offset-y: 0px;

  --qq-top-btn-size-more: 52px;
  --qq-more-offset-x: 0px;
  --qq-more-offset-y: 0px;

  --qq-top-btn-size-xinsheng: 22px;
  --qq-xinsheng-offset-x: 0px;
  --qq-xinsheng-offset-y: 0px;

  /* ==================== 2. 【角色名字控制】 ==================== */
  --qq-title-size: 18px;
  --qq-title-weight: 600;
  --qq-title-offset-x: -15px;
  --qq-title-offset-y: -6px;

  /* ==================== 3. 【名字下方装饰（零占位）】 ==================== */
  --qq-title-deco-below: url("https://771553.xyz/file/studio/gd8zmjBu8GAnSbZt.png");
  --qq-title-deco-below-w: 100px;
  --qq-title-deco-below-h: 60px;
  --qq-title-deco-below-x: -5px;
  --qq-title-deco-below-y: -20px;

  /* ==================== 4. 【名字右侧装饰图组】 ==================== */
  --qq-title-deco-r0: url("https://771553.xyz/file/studio/blcAouYncYrYl5ho.png");
  --qq-title-deco-r0-h: 14px;
  --qq-title-deco-r0-offset-x: 0px;
  --qq-title-deco-r0-offset-y: 0px;

  --qq-title-deco-r1: url("https://771553.xyz/file/studio/fH3HchtcY5SodIn5.png");
  --qq-title-deco-r2: url("https://771553.xyz/file/studio/BrFMex3bNKYjFNFl.png");
  --qq-title-deco-r3: url("https://771553.xyz/file/studio/U9wVPhriLAqlwqNj.png");
  --qq-title-deco-r1-h: 26px;
  --qq-title-deco-r2-h: 26px;
  --qq-title-deco-r3-h: 26px;
  --qq-title-deco-r-gap: 1px;
  --qq-title-deco-r-group-offset-x: 38px;
  --qq-title-deco-r-group-offset-y: 0px;

  --qq-title-deco-r-divider-w: 1.5px;
  --qq-title-deco-r-divider-h: 12px;
  --qq-title-deco-r-divider-color: #c8ccd2;
  --qq-title-deco-r-divider-offset-x: 38px;
  --qq-title-deco-r-divider-offset-y: 0px;
  --qq-title-deco-r-divider-gap: 8px;

  --qq-title-deco-r-margin-left: 6px;

  /* ==================== 5. 【顶栏功能图标图床】 ==================== */
  --qq-icon-back: url("https://771553.xyz/file/studio/KzFE67dTYIy4lhZ9.png");
  --qq-icon-xinsheng: url("https://771553.xyz/file/studio/l7moaTUphBlAUjo5.png");
  --qq-icon-more: url("https://771553.xyz/file/studio/EAeNsdZLvbrE0LJ2.png");

  /* ==================== 6. 【底栏留白与 6 个装饰按钮】 ==================== */
  --qq-bottom-blank-height: 48px;
  --qq-dock-icon-height: 22px;

  --qq-dock-icon-height-1: 22px;
  --qq-dock-icon-height-2: 19px;
  --qq-dock-icon-height-3: 20px;
  --qq-dock-icon-height-4: var(--qq-dock-icon-height);
  --qq-dock-icon-height-5: var(--qq-dock-icon-height);
  --qq-dock-icon-height-6: var(--qq-dock-icon-height);

  --qq-dock-img-1: url("https://771553.xyz/file/studio/KcQM1VeBJ7OyJUds.png");
  --qq-dock-img-2: url("https://771553.xyz/file/studio/jqIsAGMJKaD3BYlw.png");
  --qq-dock-img-3: url("https://771553.xyz/file/studio/f1cBGpeUqCiiZyq0.png");
  --qq-dock-img-4: url("https://771553.xyz/file/studio/YJRXZSzFzKKq22ab.png");
  --qq-dock-img-5: url("https://771553.xyz/file/studio/ugZS3CqB4XFt94ug.png");
  --qq-dock-img-6: url("https://771553.xyz/file/studio/gwNdGkxXKEl65Gtd.png");

  --qq-dock-left: 8%;
  --qq-dock-right: 92%;
  --qq-dock-step: calc((var(--qq-dock-right) - var(--qq-dock-left)) / 5);

  --qq-dock-pos-1: var(--qq-dock-left);
  --qq-dock-pos-2: calc(var(--qq-dock-left) + var(--qq-dock-step) * 1);
  --qq-dock-pos-3: calc(var(--qq-dock-left) + var(--qq-dock-step) * 2);
  --qq-dock-pos-4: calc(var(--qq-dock-left) + var(--qq-dock-step) * 3);
  --qq-dock-pos-5: calc(var(--qq-dock-left) + var(--qq-dock-step) * 4);
  --qq-dock-pos-6: var(--qq-dock-right);

  /* ==================== 7. 语音按钮 ==================== */
  --qq-voice-right: 90%;
  --qq-voice-bottom: -38px;
  --qq-voice-size: 32px;
  --qq-voice-opacity: 0;

  /* ==================== 8. 加号按钮 ==================== */
  --qq-plus-right: 1.4%;
  --qq-plus-bottom: -41px;
  --qq-plus-size: 32px;
  --qq-plus-opacity: 0;

  /* ==================== 9. 角色回复按钮 ==================== */
  --qq-reply-right: 1%;
  --qq-reply-bottom: 5px;
  --qq-reply-size: 32px;
  --qq-reply-opacity: 0;

  /* ==================== 10. 【输入栏可调参数】 ==================== */
  --qq-input-height: 44px;
  --qq-input-radius: 8px;
  --qq-input-font-size: 15px;
  --qq-input-padding-x: 12px;
  --qq-compose-top-space: 12px;

  /* ==================== 11. 加号展开面板 ==================== */
  --qq-popover-right: 12px;
  --qq-popover-bottom: 65px;

  /* ==================== 16. ★【输入框右上角装饰图】 ==================== */
  --qq-input-deco: url("https://771553.xyz/file/studio/vxWQ2mCnNJRoiaKX.png"); /* 装饰图链接 */
  --qq-input-deco-w: 64px;    /* 装饰图宽度：越大越宽 */
  --qq-input-deco-h: 64px;    /* 装饰图高度：越大越高 */
  --qq-input-deco-right: 8px; /* 距输入框右侧距离：正数越大越靠左 */
  --qq-input-deco-top: -18px; /* 距输入框顶部：负值越大越往上露出 */
  --qq-input-deco-z: 60;      /* 层级：需高于输入框，低于加号面板 */

  /* ==================== 17. ★【输入栏上方装饰图】 ==================== */
  --qq-compose-top-deco: url("https://771553.xyz/file/studio/5q7ourR26jBLFWHt.png"); /* 装饰图链接 */
  --qq-compose-top-deco-w: 120px;   /* 装饰图宽度：越大越宽 */
  --qq-compose-top-deco-h: 60px;    /* 装饰图高度：越大越高 */
  --qq-compose-top-deco-right: 12px;/* 距底栏右侧距离：正数越大越靠左 */
  --qq-compose-top-deco-top: -48px; /* 距底栏顶部：负值越大越往上露出 */
  --qq-compose-top-deco-z: 49;      /* 层级：低于输入框、高于底栏背景 */
}

/* ============================================================
   一、顶栏布局与名字区域
   ============================================================ */

.chat-thread-top {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: var(--qq-header-height) !important;
  padding: 0 !important;
  background: transparent !important;
  z-index: 50;
}

.chat-thread-pill {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: var(--qq-header-height) !important;
  background: #f5f6fa !important;
  border-radius: 0 !important;
  border: none !important;
  border-bottom: 1px solid #e6e8eb !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  display: flex !important;
  align-items: flex-end !important;
  padding: 0 12px var(--qq-header-safe-bottom) 12px !important;
  box-sizing: border-box !important;
}

.chat-thread-center {
  flex: 1 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  transform: translate(var(--qq-title-offset-x), var(--qq-title-offset-y)) !important;
  overflow: visible !important;
  position: relative !important;
}

.chat-thread-center h2 {
  font-size: var(--qq-title-size) !important;
  font-weight: var(--qq-title-weight) !important;
  color: #111 !important;
  margin: 0 !important;
  position: relative !important;
  overflow: visible !important;
  display: inline-flex !important;
  align-items: center !important;
}

.chat-thread-center h2::after {
  content: "" !important;
  position: absolute !important;
  left: var(--qq-title-deco-below-x) !important;
  top: calc(100% + var(--qq-title-deco-below-y)) !important;
  width: var(--qq-title-deco-below-w) !important;
  height: var(--qq-title-deco-below-h) !important;
  background-image: var(--qq-title-deco-below) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: left top !important;
  pointer-events: none !important;
  z-index: 5 !important;
}

.chat-thread-center::after {
  content: "" !important;
  display: inline-block !important;
  vertical-align: middle !important;
  height: calc(
    max(
      var(--qq-title-deco-r0-h),
      var(--qq-title-deco-r1-h),
      var(--qq-title-deco-r2-h),
      var(--qq-title-deco-r3-h),
      var(--qq-title-deco-r-divider-h)
    )
    + 20px
  ) !important;
  width: calc(
    var(--qq-title-deco-r0-h)
    + var(--qq-title-deco-r-divider-gap) * 2
    + var(--qq-title-deco-r-divider-w)
    + var(--qq-title-deco-r1-h)
    + var(--qq-title-deco-r-gap)
    + var(--qq-title-deco-r2-h)
    + var(--qq-title-deco-r-gap)
    + var(--qq-title-deco-r3-h)
    + var(--qq-title-deco-r-divider-offset-x)
    + var(--qq-title-deco-r-group-offset-x)
    + 10px
  ) !important;
  margin-left: var(--qq-title-deco-r-margin-left) !important;
  background-image:
    var(--qq-title-deco-r0),
    linear-gradient(var(--qq-title-deco-r-divider-color), var(--qq-title-deco-r-divider-color)),
    var(--qq-title-deco-r1),
    var(--qq-title-deco-r2),
    var(--qq-title-deco-r3) !important;
  background-size:
    auto var(--qq-title-deco-r0-h),
    var(--qq-title-deco-r-divider-w) var(--qq-title-deco-r-divider-h),
    auto var(--qq-title-deco-r1-h),
    auto var(--qq-title-deco-r2-h),
    auto var(--qq-title-deco-r3-h) !important;
  background-repeat: no-repeat !important;
  background-position:
    calc(0px + var(--qq-title-deco-r0-offset-x)) calc(50% + var(--qq-title-deco-r0-offset-y)),
    calc(
      var(--qq-title-deco-r0-h)
      + var(--qq-title-deco-r-divider-gap)
      + var(--qq-title-deco-r-divider-offset-x)
    ) calc(50% + var(--qq-title-deco-r-divider-offset-y)),
    calc(
      var(--qq-title-deco-r0-h)
      + var(--qq-title-deco-r-divider-gap) * 2
      + var(--qq-title-deco-r-divider-w)
      + var(--qq-title-deco-r-group-offset-x)
    ) calc(50% + var(--qq-title-deco-r-group-offset-y)),
    calc(
      var(--qq-title-deco-r0-h)
      + var(--qq-title-deco-r-divider-gap) * 2
      + var(--qq-title-deco-r-divider-w)
      + var(--qq-title-deco-r1-h)
      + var(--qq-title-deco-r-gap)
      + var(--qq-title-deco-r-group-offset-x)
    ) calc(50% + var(--qq-title-deco-r-group-offset-y)),
    calc(
      var(--qq-title-deco-r0-h)
      + var(--qq-title-deco-r-divider-gap) * 2
      + var(--qq-title-deco-r-divider-w)
      + var(--qq-title-deco-r1-h)
      + var(--qq-title-deco-r-gap)
      + var(--qq-title-deco-r2-h)
      + var(--qq-title-deco-r-gap)
      + var(--qq-title-deco-r-group-offset-x)
    ) calc(50% + var(--qq-title-deco-r-group-offset-y)) !important;
  pointer-events: none !important;
  z-index: 5 !important;
}

.chat-thread-pill .chat-back {
  background-image: var(--qq-icon-back) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: var(--qq-top-btn-size) !important;
  height: var(--qq-top-btn-size) !important;
  color: transparent !important;
  transform: translate(var(--qq-back-offset-x), var(--qq-back-offset-y)) !important;
}
.chat-thread-pill .chat-back svg { display: none !important; }

.chat-thread-head-xinsheng {
  background-image: var(--qq-icon-xinsheng) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: var(--qq-top-btn-size-xinsheng) !important;
  height: var(--qq-top-btn-size-xinsheng) !important;
  color: transparent !important;
  transform: translate(var(--qq-xinsheng-offset-x), var(--qq-xinsheng-offset-y)) !important;
}
.chat-thread-head-xinsheng svg { display: none !important; }

.chat-thread-head-more {
  background-image: var(--qq-icon-more) !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: var(--qq-top-btn-size-more) !important;
  height: var(--qq-top-btn-size-more) !important;
  color: transparent !important;
  transform: translate(var(--qq-more-offset-x), var(--qq-more-offset-y)) !important;
}
.chat-thread-head-more svg { display: none !important; }

/* ============================================================
   二、消息区域留白
   ============================================================ */

.chat-thread-scroll {
  padding-top: calc(var(--qq-header-height) + 12px) !important;
  padding-bottom: calc(
    60px
    + var(--qq-bottom-blank-height)
    + var(--qq-compose-top-space)
    + env(safe-area-inset-bottom, 6px)
  ) !important;
}

/* ============================================================
   三、底栏通栏与 6 个装饰图床按钮
   ============================================================ */

.chat-compose {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  background: #f5f6fa !important;
  border-top: 1px solid #e6e8eb !important;
  border-radius: 0 !important;
  padding-top: var(--qq-compose-top-space) !important;
  padding-bottom: calc(var(--qq-bottom-blank-height) + env(safe-area-inset-bottom, 6px)) !important;
  z-index: 50;
  box-sizing: border-box !important;
  overflow: visible !important;
}

.chat-compose-bar,
.chat-compose-bar > div:not(.chat-compose-popover),
.chat-compose-bar > span {
  position: static !important;
  overflow: visible !important;
}

.chat-compose-bar {
  background: #ffffff !important;
  border: 1px solid #e6e8eb !important;
  border-radius: var(--qq-input-radius) !important;
  box-shadow: none !important;
  min-height: var(--qq-input-height) !important;
  height: var(--qq-input-height) !important;
  max-height: var(--qq-input-height) !important;
  padding: 0 var(--qq-input-padding-x) !important;
  display: flex !important;
  align-items: center !important;
  box-sizing: border-box !important;
  position: relative !important;
  overflow: visible !important;
}

.chat-compose-bar textarea,
.chat-compose-bar input[type="text"] {
  font-size: var(--qq-input-font-size) !important;
  line-height: 1.4 !important;
  height: 100% !important;
  min-height: 0 !important;
  max-height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  resize: none !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

.chat-compose::after {
  content: "";
  position: absolute;
  bottom: env(safe-area-inset-bottom, 6px);
  left: 0;
  right: 0;
  height: var(--qq-bottom-blank-height);
  pointer-events: none !important;
  background-image:
    var(--qq-dock-img-1),
    var(--qq-dock-img-2),
    var(--qq-dock-img-3),
    var(--qq-dock-img-4),
    var(--qq-dock-img-5),
    var(--qq-dock-img-6);
  background-size:
    auto var(--qq-dock-icon-height-1),
    auto var(--qq-dock-icon-height-2),
    auto var(--qq-dock-icon-height-3),
    auto var(--qq-dock-icon-height-4),
    auto var(--qq-dock-icon-height-5),
    auto var(--qq-dock-icon-height-6);
  background-repeat: no-repeat;
  background-position:
    var(--qq-dock-pos-1) center,
    var(--qq-dock-pos-2) center,
    var(--qq-dock-pos-3) center,
    var(--qq-dock-pos-4) center,
    var(--qq-dock-pos-5) center,
    var(--qq-dock-pos-6) center;
}

/* ============================================================
   四、三个功能按钮
   ============================================================ */

.chat-compose-bar button,
.chat-compose > button,
.chat-compose-plus,
.chat-compose-more,
.chat-compose-btn-plus {
  display: flex !important;
  visibility: visible !important;
  position: absolute !important;
  right: var(--qq-plus-right) !important;
  bottom: calc(env(safe-area-inset-bottom, 6px) + var(--qq-plus-bottom)) !important;
  left: auto !important;
  top: auto !important;
  transform: none !important;
  width: var(--qq-plus-size) !important;
  height: var(--qq-plus-size) !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 998 !important;
  pointer-events: auto !important;
  opacity: var(--qq-plus-opacity) !important;
  background: rgba(60, 150, 255, 0.45) !important;
  border-radius: 6px !important;
}

.chat-compose-bar > button:first-of-type:not([class*="plus"]):not([class*="more"]):not([class*="add"]):not([class*="attach"]):not([aria-label*="更多"]):not([aria-label*="加"]),
.chat-compose-bar button:first-child:not([class*="plus"]):not([class*="more"]):not([class*="add"]):not([class*="attach"]):not([aria-label*="更多"]):not([aria-label*="加"]),
.chat-compose-bar .chat-compose-voice,
.chat-compose-bar .chat-compose-btn-voice,
.chat-compose-bar button[class*="voice"],
.chat-compose-bar button[class*="mic"],
.chat-compose-bar button[class*="audio"],
.chat-compose-bar button[aria-label*="语音"],
.chat-compose-bar button[title*="语音"] {
  display: flex !important;
  visibility: visible !important;
  position: absolute !important;
  right: var(--qq-voice-right) !important;
  bottom: calc(env(safe-area-inset-bottom, 6px) + var(--qq-voice-bottom)) !important;
  left: auto !important;
  top: auto !important;
  transform: none !important;
  width: var(--qq-voice-size) !important;
  height: var(--qq-voice-size) !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 999 !important;
  pointer-events: auto !important;
  opacity: var(--qq-voice-opacity) !important;
  background: rgba(255, 80, 80, 0.45) !important;
  border-radius: 6px !important;
}

.chat-compose-bar .chat-compose-reply,
.chat-compose-bar .chat-compose-char-reply,
.chat-compose-bar .chat-compose-role-reply,
.chat-compose-bar .chat-compose-btn-reply,
.chat-compose-bar button[class*="reply"],
.chat-compose-bar button[class*="char"],
.chat-compose-bar button[class*="role"],
.chat-compose-bar button[class*="ai"],
.chat-compose-bar button[class*="spark"],
.chat-compose-bar button[class*="wait"],
.chat-compose-bar button[aria-label*="回复"],
.chat-compose-bar button[aria-label*="角色"],
.chat-compose-bar button[title*="回复"],
.chat-compose-bar button[title*="角色"],
.chat-compose .chat-compose-reply,
.chat-compose .chat-compose-char-reply,
.chat-compose .chat-compose-role-reply,
.chat-compose button[class*="reply"] {
  display: flex !important;
  visibility: visible !important;
  position: absolute !important;
  right: var(--qq-reply-right) !important;
  bottom: calc(env(safe-area-inset-bottom, 6px) + var(--qq-reply-bottom)) !important;
  left: auto !important;
  top: auto !important;
  transform: none !important;
  width: var(--qq-reply-size) !important;
  height: var(--qq-reply-size) !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 1000 !important;
  pointer-events: auto !important;
  opacity: var(--qq-reply-opacity) !important;
  background: rgba(60, 200, 100, 0.45) !important;
  border-radius: 6px !important;
}

.chat-compose-bar .chat-compose-send,
.chat-compose-bar .chat-compose-btn-send,
.chat-compose-bar button[class*="send"],
.chat-compose-bar button[type="submit"],
.chat-compose-bar button[aria-label*="发送"],
.chat-compose-bar button[title*="发送"],
.chat-compose .chat-compose-send,
.chat-compose-sticker-suggest button {
  display: none !important;
  visibility: hidden !important;
  width: 0 !important;
